site.platform.agentpage.doctrinecss-1:
.md { max-width: var(--paper-measure); }
.md h2.md-h {
  font-size: 21px; margin: var(--space-8) 0 0;
  padding-top: var(--space-4); border-top: 1px solid var(--rule);
}
/* A doctrine file usually writes `---` right before its next `##`. Both would
   draw a line, so the authored rule yields to the heading's own — which keeps the
   separator at one weight whether or not the author happened to type the dashes. */
.md .md-hr:has(+ h2.md-h) { display: none; }
.md h3.md-h { margin: var(--space-6) 0 0; }
.md h4.md-h { font-size: 13px; margin: var(--space-4) 0 0; color: var(--ink-soft); }
.md .md-p { font-size: 14px; line-height: 1.65; color: var(--ink-soft); margin: var(--space-3) 0 0; }
.md .md-list {
  font-size: 14px; line-height: 1.6; color: var(--ink-soft);
  margin: var(--space-3) 0 0; padding-left: var(--space-5);
}
.md .md-list li { margin-bottom: var(--space-1); }
.md .md-quote {
  margin: var(--space-4) 0 0; padding: var(--space-3) var(--space-4);
  font-size: 14px; line-height: 1.6; color: var(--ink-soft); background: var(--bg-sunk);
  border-left: 2px solid var(--accent); border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}
.md .md-pre {
  margin: var(--space-4) 0 0; padding: var(--space-3) var(--space-4); overflow-x: auto;
  background: var(--bg-sunk); border: 1px solid var(--rule-soft); border-radius: var(--radius-sm);
}
.md .md-pre code { font-size: 13px; line-height: 1.55; color: var(--ink-soft); }
.md code { color: var(--ink); }
.md .md-hr { border: 0; border-top: 1px solid var(--rule-soft); margin: var(--space-6) 0 0; }
.md .md-table-wrap { max-width: var(--paper-wide); overflow-x: auto; margin: var(--space-4) 0 0; }
.md .md-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.md .md-table th {
  text-align: left; padding: var(--space-2) var(--space-3) var(--space-2) 0;
  border-bottom: 1px solid var(--rule);
  font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--ink-faded); font-weight: 400; white-space: nowrap;
}
.md .md-table td {
  padding: var(--space-2) var(--space-3) var(--space-2) 0;
  border-bottom: 1px solid var(--rule-soft);
  color: var(--ink-soft); line-height: 1.5; vertical-align: top;
}
.md a { color: var(--accent); }

